// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays.
func (r *GraphQLAgendaRepository) Delete(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "agendas"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	if _, err := r.Svc.Mutation.DeepV1.Agendas.UpdateIfMatch(ctx, id, r.deletePatch(), agendasql.DeleteTime.IsNull(true)); err != nil {
		if errors.Is(err, graphql.ErrConflict) {
			return repox.ErrNotFound
		}
		return mapGraphQLErr(err)
	}
	return nil
}

// deletePatch is the write that soft-deletes a record now: Delete's, and a
// Batch's.
func (r *GraphQLAgendaRepository) deletePatch() agendasql.UpdateInput {
	at := time.Now().UTC()
	now := at.Format(time.RFC3339Nano)
	patch := agendasql.UpdateInput{DeleteTime: graphql.Value(now)}
	patch.Etag = graphql.Value(repox.NewULID())
	return patch
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GraphQLAgendaRepository) Undelete(ctx context.Context, name string) (*deepv1.Agenda, error) {
	id, err := r.rowID(ctx, name)
	if err != nil {
		return nil, err
	}
	patch := agendasql.UpdateInput{DeleteTime: graphql.Null[string]()}
	patch.Etag = graphql.Value(repox.NewULID())
	if _, err := r.Svc.Mutation.DeepV1.Agendas.UpdateIfMatch(ctx, id, patch, agendasql.DeleteTime.IsNull(false)); err != nil {
		if !errors.Is(err, graphql.ErrConflict) {
			return nil, mapGraphQLErr(err)
		}
		if _, err := r.get(ctx, id); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, id)
}

// Purge removes the record addressed by its resource name for good.
func (r *GraphQLAgendaRepository) Purge(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "agendas"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	_, err = r.purge(ctx, id, name, true)
	return err
}

// purge removes row id, named name, for good -- unless something still
// refers to it, when it keeps the row and reports kept: a row of this
// database holding a foreign key to it (asked first, see referenced, then caught
// again from the database's own refusal), or, when askReferrers, a referrer
// in another database or service (r.Refs). A purge never fails, and never
// cascades, because of a referrer. repox.ErrNotFound when there is no such
// row.
func (r *GraphQLAgendaRepository) purge(ctx context.Context, id, name string, askReferrers bool) (kept bool, err error) {
	if referenced, err := r.referenced(ctx, nil, id, name); err != nil {
		return false, err
	} else if referenced {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	if askReferrers && r.Refs.KeepOnPurge(ctx, "deep.v1/Agenda", name) {
		return true, nil
	}
	err = r.remove(ctx, id)
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

