// Create persists in under parent and returns the stored record.
func (r *GraphQLMeetingRepository) Create(ctx context.Context, parent string, in *deepv1.Meeting) (*deepv1.Meeting, error) {
	parentIDs, err := repox.SplitName(parent, "agendas")
	if err != nil {
		return nil, err
	}
	id := repox.NewULID()
	rowID := id
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "agendas", "meetings")
		if err != nil {
			return nil, err
		}
		for i := range parentIDs {
			if ids[i] != parentIDs[i] {
				return nil, fmt.Errorf("%w: name %q is not under parent %q", repox.ErrInvalidArgument, in.GetName(), parent)
			}
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*deepv1.Meeting)
	in.Name = FormatMeetingName(parentIDs[0], id)
	// The id is unique only under the parent, so the row is keyed by a
	// surrogate of its own: the id itself only when it was minted here.
	id = rowID
	if h := r.Hooks.BeforeCreate; h != nil {
		if err := h(ctx, in); err != nil {
			return nil, err
		}
	}
	ci := meetingToCreateInput(in)
	ci.Id = id
	ci.AgendaId = parentIDs[0]
	ci.Etag = repox.NewULID()
	if v := in.GetStart(); v != nil {
		vi := deepV1MomentToCreateInput(v)
		vi.Id = repox.NewULID()
		if _, err := r.Svc.Mutation.DeepV1.Moments.Create(ctx, vi); err != nil {
			return nil, mapGraphQLErr(err)
		}
		ci.StartId = vi.Id
	}
	if v := in.GetEnd(); v != nil {
		vi := deepV1MomentToCreateInput(v)
		vi.Id = repox.NewULID()
		if _, err := r.Svc.Mutation.DeepV1.Moments.Create(ctx, vi); err != nil {
			return nil, mapGraphQLErr(err)
		}
		ci.EndId = vi.Id
		ci.EndsCase = "END"
	}
	// One transaction: the graph lands whole or not at all.
	gtx := r.Svc.Mutation.Tx()
	if v1 := in.GetRule(); v1 != nil {
		n2 := deepV1RuleToCreateInput(v1)
		n2.Id = repox.NewULID()
		if v3 := v1.GetUntil(); v3 != nil {
			n4 := deepV1MomentToCreateInput(v3)
			n4.Id = repox.NewULID()
			gtx.Add(r.Svc.Mutation.DeepV1.Moments.CreateOp(n4, new(momentsql.InsertDeepV1MomentsResponse)))
			n2.UntilId = n4.Id
			n2.BoundCase = "UNTIL"
		}
		gtx.Add(r.Svc.Mutation.DeepV1.Rules.CreateOp(n2, new(rulesql.InsertDeepV1RulesResponse)))
		for _, v5 := range v1.GetDays() {
			n6 := deepV1DayToCreateInput(v5)
			n6.Id = repox.NewULID()
			n6.RuleId = n2.Id
			gtx.Add(r.Svc.Mutation.DeepV1.Days.CreateOp(n6, new(daysql.InsertDeepV1DaysResponse)))
		}
		ci.RuleId = n2.Id
	}
	gtx.Add(r.Svc.Mutation.DeepV1.Meetings.CreateOp(ci, new(meetingsql.InsertDeepV1MeetingsResponse)))
	if err := gtx.Commit(ctx); err != nil {
		return nil, mapGraphQLErr(err)
	}
	return r.get(ctx, id)
}

